comms.text:
@1 אַתּוּן קָיְמִין יוֹמָא דֵין כֻּלְכוֹן קֳדָם יְיָ אֱלָהֲכוֹן רֵישֵׁיכוֹן שִׁבְטֵיכוֹן סָבֵיכוֹן וְסָרְכֵיכוֹן כָּל אֱנַשׁ יִשְׂרָאֵל:
@2 טַפְלְכוֹן נְשֵׁיכוֹן וְגִיוֹרָךְ דִי בְּגוֹ מַשְׁרִיתָךְ מִלָקֵטּ אָעָיךְ עַד מְלֵי מַיָיךְ:
@3 לְאָעָלוּתָךְ בִּקְיָמָא דַיְיָ אֱלָהָךְ וּבְמוֹמָתֵהּ דִי יְיָ אֱלָהָךְ גְזַר עִמָךְ יוֹמָא דֵין:
@4 בְּדִיל לַאֲקָמָא יָתָךְ יוֹמָא דֵין קֳדָמוֹהִי לְעַמָא וְהוּא יְהֵי לָךְ לֶאֶלָהּ כְּמָא דִי מַלִיל לָךְ וּכְמָא דִי קַיִים לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב:
@5 וְלָא עִמְכוֹן בִּלְחוֹדֵיכוֹן אֲנָא גְזַר יָת קְיָמָא הָדָא וְיָת מוֹמָתָא הָדָא:
@6 אֲרֵי יָת מָן דְאִיתוֹהִי הָכָא עִמָנָא קָאֵם יוֹמָא דֵין קֳדָם יְיָ אֱלָהָנָא וְיָת מָן דְלֵיתוֹהִי הָכָא עִמָנָא יוֹמָא דֵין:
@7 אֲרֵי אַתּוּן יְדַעְתּוּן יָת דִיתֵבְנָא בְּאַרְעָא דְמִצְרָיִם וְיָת דִי עֲבַרְנָא בְּגוֹ עַמְמַיָא דִי עֲבַרְתּוּן:
@8 וַחֲזֵיתוּן יָת שִׁקוּצֵיהוֹן וְיָת טַעֲוָתְהוֹן אָעָא וְאַבְנָא כַּסְפָּא וְדַהֲבָא דִי עִמְהוֹן:
@9 דִילְמָא אִית בְּכוֹן גְבַר אוֹ אִתְּתָא אוֹ זַרְעִית אוֹ שִׁבְטָא דִי לִבֵּהּ פָּנֵי יוֹמָא דֵין מִדַחַלְתָּא דַייָ אֱלָהָנָא לִמְהַךְ לְמִפְלַח יָת טַעֲוַת עַמְמַיָא הָאִנוּן דִילְמָא אִית בְּכוֹן גְבַר מְהַרְהַר חֶטְאִין אוֹ זָדוֹן:
@10 וִיהֵי בְּמִשְׁמְעֵהּ יָת פִּתְגָמֵי מוֹמָתָא הָדָא וִיחַשַׁב בְּלִבֵּהּ לְמֵימַר שְׁלָמָא יְהֵי לִי אֲרֵי בְּהַרְהוֹר לִבִּי אֲנָא אָזֵל בְּדִיל לְאוֹסָפָא לֵהּ חֶטְאֵי שָׁלוּתָא עַל זְדָנוּתָא:
@11 לָא יֵיבֵי יְיָ לְמִשְׁבַּק לֵהּ אֲרֵי בְּכֵן יִתְקֵף רָגְזָא דַיְיָ וְחֶמְתֵהּ בְּגַבְרָא הַהוּא וְיִדְבְּקוּן בֵּהּ כָּל לְוָטַּיָא דִכְתִיבִין בְּסִפְרָא הָדֵין וְיִמְחֵי יְיָ יָת שְׁמֵהּ מִתְּחוֹת שְׁמַיָא:
@12 וְיַפְרְשִׁנֵהּ יְיָ לְבִישָׁא מִכֹּל שִׁבְטַיָא דְיִשְׂרָאֵל כְּכֹל לְוָטֵי קְיָמָא דִכְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדֵין:
@13 וְיֵימַר דָרָא בַתְרָאָה בְּנֵיכוֹן דִי יְקוּמוּן מִבַּתְרֵיכוֹן וּבַר עַמְמִין דִי יֵיתֵי מֵאַרְעָא רְחִיקָא וְיֶחֱזוּן יָת מְחָתָא דְאַרְעָא הַהִיא וְיָת מַרְעָהָא דִי אַמְרַע יְיָ בַּהּ:
@14 גָפְרֵתָא וּמִלְחָא יְקִידַת כָּל אַרְעַהּ לָא תִזְרַע וְלָא תַצְמַח וְלָא יִסַק בַּהּ כָּל עֶסְבָּא כְּמַהְפֶּכְתָּא דִסְדֹם וַעֲמֹרָה אַדְמָה וּצְבוֹיִם דִי הֲפַךְ יְיָ בְּרָגְזֵהּ וּבְחֶמְתֵהּ:
@15 וְיֵימְרוּן כָּל עַמְמַיָא עַל מֶה עֲבַד יְיָ כְּדֵין לְאַרְעָא הָדָא מָא תְקוֹף רָגְזָא רַבָּא הָדֵין:
@16 וְיֵימְרוּן עַל דִשְׁבָקוּ יָת קְיָמָא דַיְיָ אֱלָהָא דַאֲבָהָתְהוֹן דִי גְזַר עִמְהוֹן בְּאַפָּקוּתֵהּ יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם:
@17 וַאֲזָלוּ וּפְלָחוּ לְטַעֲוַת עַמְמַיָא וּסְגִידוּ לְהוֹן דַחֲלָן דִי לָא יְדָעֻנוּן וְלָא אוֹטִיבָא לְהוֹן:
@18 וּתְקֵף רָגְזָא דַיְיָ בְּאַרְעָא הַהִיא לְאַיְתָאָה עֲלַהּ יָת כָּל לְוָטַיָא דִכְתִיבִין בְּסִפְרָא הָדֵין:
@19 וְטַּלְטְּלִנוּן יְיָ מֵעַל אַרְעֲהוֹן בִּרְגַז וּבְחֵמְתָא וּבִתְקוֹף רְגַז וְאַגְלִנוּן לְאַרְעָא אָחֳרִי כְּיוֹמָא הָדֵין:
@20 דְמִטַמְרָן קֳדָם יְיָ אֱלָהָנָא וּדְמִגַלְיָן לָנָא וְלִבְנָנָא עַד עֳלָם לְמֶעְבַּד יָת כָּל פִּתְגָמֵי אוֹרַיְתָא הָדָא:
@21 וִיהֵי אֲרֵי יֵיתוּן עֲלָךְ כָּל פִּתְגָמַיָא הָאִלֵין בִּרְכָן וּלְוָטִין דִי יְהָבִית קֳדָמָךְ וּתְתוּב לְלִבָּךְ בְּכָל עַמְמַיָא דִי אַגְלָךְ יְיָ אֱלָהָךְ לְתַמָן:
@22 וּתְתוּב לְדַחַלְתָּא דַיְיָ אֱלָהָךְ וּתְקַבֵּל לְמֵימְרֵהּ כְּכֹל דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין אַתְּ וּבְנָיךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@23 וִיתוּב יְיָ אֱלָהָךְ יָת שְׁבִי גַלְוָתָךְ וִירַחַם עֲלָךְ וִיתוּב וְיִכְנְשִׁנָךְ מִכָּל עַמְמַיָא דִי בַדְרָךְ יְיָ אֱלָהָךְ לְתַמָן:
@24 אִם יְהֵי גַלְוָתָךְ בִּסְיָפֵי שְׁמַיָא מִתַּמָן יִכְנְשִׁנָךְ יְיָ אֱלָהָךְ וּמִתַּמָן יְקָרְבִנָךְ:
@25 וְיָעֵלִנָךְ יְיָ אֱלָהָךְ לְאַרְעָא דִירִיתוּ אֲבָהָתָךְ וְתֵרְתַהּ וְיוֹטֶב לָךְ וְיַסְגִנָךְ מֵאֲבְהָתָךְ:
@26 וְיֶעְדֵי יְיָ אֱלָהָךְ יָת טַפְשׁוּת לִבָּךְ וְיָת טַּפְשׁוּת לִבָּא דִבְנָיךְ לְמִרְחַם יָת יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ בְּדִיל חַיָיךְ:
@27 וְיִתֵּן יְיָ אֱלָהָךְ יָת כָּל לְוָטַיָא הָאִלֵין עַל בַּעֲלֵי דְבָבָךְ וְעַל סָנְאָךְ דִי רְדָפוּךְ:
@28 וְאַתְּ תְּתוּב וּתְקַבַּל לְמֵימְרָא דַיְיָ וְתַעְבֵּד יָת כָּל פִּקוּדוֹהִי דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין:
@29 וְיוֹתְרִינָךְ יְיָ אֱלָהָךְ בְּכֹל עוֹבָדֵי יְדָךְ בְּוַלְדָא דִמְעָךְ וּבְוַלְדָא דִבְעִירָךְ וּבְאִבָּא דְאַרְעָךְ לְטָּבָא אֲרֵי יְתוּב יְיָ לְמֶחֱדֵי עֲלָךְ לְטָב כְּמָא דִי חֲדִי עַל אֲבָהָתָךְ:
@30 אֲרֵי תְקַבַּל בְּמֵימְרָא דַיְיָ אֱלָהָךְ לְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי דִכְתִיבִין בְּסִפְרָא דְאוֹרַיְתָא הָדֵין אֲרֵי תְתוּב קֳדָם יְיָ אֱלָהָךְ בְּכָל לִבָּךְ וּבְכָל נַפְשָׁךְ:
@31 אֲרֵי תַּפְקֶדְתָּא הָדָא דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לָא מַפְרְשָׁא הִיא מִנָךְ וְלָא רְחִיקָא הִיא:
@32 לָא בִשְׁמַיָא הִיא לְמֵימָר מָן יִסַק לָנָא לִשְׁמַיָא וְיִסְבַהּ לָנָא וְיַשְׁמְעִנָנָא יָתַהּ וְנַעְבְּדִנַהּ:
@33 וְלָא מֵעִבְרָא לְיַמָא הִיא לְמֵימַר מָן יֵעִבַר לָנָא לְעִבְרָא דְיַמָא וְיִסְבַהּ לָנָא וְיַשְׁמְעִנָנָא יָתַהּ וְנַעְבְּדִנַהּ:
@34 אֲרֵי קָרִיב לָךְ פִּתְגָמָא לַחֲדָא בְּפוּמָךְ וּבְלִבָּךְ לְמֶעְבְּדֵהּ:
@35 חֲזֵי דִיהָבִית קֳדָמָךְ יוֹמָא דֵין יָת חַיֵי וְיָת טַבְתָא וְיָת מוֹתָא וְיָת בִּישָׁא:
@36 דִי אֲנָא מְפַקְדָךְ יוֹמָא דֵין לְמִרְחַם יָת יְיָ אֱלָהָךְ לִמְהַךְ בְּאָרְחָן דְתָקְנָן קֳדָמוֹהִי וּלְמִטַר פִּקוּדוֹהִי וּקְיָמוֹהִי וְדִינוֹהִי וְתֵיחֵי וְתִסְגֵי וִיבָרֵכִנָךְ יְיָ אֱלָהָךְ בְּאַרְעָא דִי אַתְּ עָלֵל לְתַמָן לְמֵירְתַהּ:
@37 וְאִם יִפְנֵי לִבָּךְ וְלָא תְקַבֵּל וְתִטְּעֵי וְתִסְגוּד לְטַּעֲוַת עַמְמַיָא וְתִפְלְחִנוּן:
@38 חַוֵיתִי לְכוֹן יוֹמָא דֵין אֲרֵי מֵיבַד תֵּיבְדוּן לָא תוֹרְכוּן יוֹמִין עַל אַרְעָא דִי אַתְּ עָבֵר יָת יַרְדְנָא לְמֵעַל לְתַמָן לְמֵירְתַהּ:
@39 אַסְהֵדִית בְּכוֹן יוֹמָא דֵין יָת שְׁמַיָא וְיָת אַרְעָא חַיֵי וּמוֹתָא יְהָבִית קֳדָמָךְ בִּרְכָן וּלְוָטִין וְתִתִּרְעֵי בְּחַיֵי בְּדִיל דְתֵיחֵי אַתְּ וּבְנָיךְ:
@40 לְמִרְחַם יָת יְיָ אֱלָהָךְ לְקַבָּלָא לְמֵימְרֵהּ וּלְאִתְקְרָבָא לְדַחַלְתֵּהּ אֲרֵי הוּא חַיָיךְ וְאוֹרָכוּת יוֹמָיךְ לְמִתַּב עַל אַרְעָא דִי קַיִים יְיָ לַאֲבָהָתָךְ לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב לְמִתַּן לְהוֹן: פפפ:

@1 **אתם נצבים.** מלמד שכנסם משה לפני הקדוש ברוך הוא ביום מותו להכניסם בברית: **ראשיכם שבטיכם.** ראשיכם לשבטיכם: **זקניכם ושטריכם.** החשוב חשוב קודם, ואחר כך כל איש ישראל:
@2 **מחטב עציך.** מלמד שבאו כנענים להתגיר בימי משה, כדרך שבאו גבעונים בימי יהושע. וזהו האמור בגבעונים (יהושע ט, ד) ויעשו גם המה בערמה, ונתנם משה חוטבי עצים ושואבי מים:
@3 **לעברך.** להיותך עובר בברית. ולא יתכן לפרשו כמו להעבירך, אלא כמו (לעיל ד, יד) לעשותכם אותם: **לעברך בברית.** דרך העברה, כך היו כורתים ברית, עושין מחצה מכאן ומחצה מכאן ועוברים בנתים, כמו שנאמר (ירמיה לד, יח) העגל אשר כרתו לשנים ויעברו בין בתריו:
@4 **למען הקים אתך היום לו לעם.** כל כך הוא נכנס לטרוח למען קים אתך לפניו לעם: **והוא יהיה לך לאלהים.** לפי שדבר לך ונשבע לאבותיך שלא להחליף את זרעם באמה אחרת, לכך הוא אוסר אתכם בשבועות הללו, שלא תקניטוהו אחר שהוא אינו יכול להבדל מכם. עד כאן פרשתי לפי פשוטו של פרשה. ומדרש אגדה, למה נסמכה פרשת אתם נצבים לקללות, לפי ששמעו ישראל מאה קללות חסר שתים, חוץ ממ''ט שבתורת כהנים, הוריקו פניהם ואמרו מי יוכל לעמוד באלו, התחיל משה לפיסם אתם נצבים היום, הרבה הכעסתם למקום ולא עשה אתכם כליה והרי אתם קימים לפניו: **היום.** כיום הזה שהוא קים והוא מאפיל ומאיר, כך האיר לכם וכך עתיד להאיר לכם, והקללות והיסורין מקימין אתכם ומציבין אתכם לפניו. ואף הפרשה של מעלה מזו פיוסין הם (לעיל פסוק א') , אתם ראיתם את כל אשר עשה. דבר אחר, אתם נצבים. לפי שהיו ישראל יוצאין מפרנס לפרנס ממשה ליהושע, לפיכך עשה אותם מצבה כדי לזרזם. וכן עשה יהושע, וכן שמואל (שמואל א' יב, ז) התיצבו ואשפטה אתכם, כשיצאו מידו ונכנסו לידו של שאול:
@6 **ואת אשר איננו פה.** ואף עם דורות העתידים להיות:
@7 **כי אתם ידעתם** וגו' **ותראו את שקוציהם.** לפי שראיתם האמות עובדי עבודה זרה ושמא השיא לב אחד מכם אותו ללכת אחריהם, פן יש בכם וגו' (פסוק יז) לפיכך אני צריך להשביעכם:
@8 **ותראו את שקוציהם.** על שם שהם מאוסים כשקצים: **גלליהם.** שמסרחים ומאוסין כגלל: **עץ ואבן.** אותן של עצים ושל אבנים ראיתם בגלוי, לפי שאין הגוים יראים שמא יגנבו, אבל של כסף וזהב, עמהם, בחדרי משכיתם הם, לפי שהם יראים שמא יגנבו:
@9 **פן יש בכם.** שמא יש בכם: **אשר לבבו פנה היום.** מלקבל עליו הברית: **שרש פרה ראש ולענה.** שרש מגדל עשב מר כגידין, שהם מרים, כלומר מפרה ומרבה רשע בקרבכם:
@10 **והתברך בלבבו.** לשון ברכה, יחשב בלבו ברכת שלום לעצמו לאמר, לא יבואוני קללות הללו, אך שלום יהיה לי: **והתברך.** בינדיר''א שי''י בלע''ז [יברך את עצמו] , כמו והתגלח והתפלל: **בשררות לבי אלך.** במראית לבי, כמו (במדבר כד, יז) אשורנו ולא קרוב, כלומר מה שלבי רואה לעשות: **למען ספות הרוה.** לפי שאוסיף לו פרענות על מה שעשה עד הנה בשוגג והייתי מעביר עליהם, וגורם עתה שאצרפם עם המזיד ואפרע ממנו הכל. וכן תרגם אנקלוס בדיל לאוספא ליה חטאי שלותא על זדנותא, שאוסיף לו אני השגגות על הזדונות: **הרוה.** שוגג שהוא עושה כאדם שכור שלא מדעת: **הצמאה.** שהוא עושה מדעת ובתאוה:
@11 **יעשן אף ה'.** על ידי כעס הגוף מתחמם והעשן יוצא מן האף, וכן (ש''ב כב, ט) עלה עשן באפו, ואף על פי שאין זו לפני המקום, הכתוב משמיע את האזן כדרך שהיא רגילה ויכולה לשמוע, כפי דרך הארץ: **וקנאתו.** לשון חמה אנפרטמינ''ט [חמה] אחיזת לבישת נקמה, ואינו מעביר על המדה:
@12 **הכתובה בספר התורה הזה.** ולמעלה הוא אומר (לעיל כח, סא) בספר התורה הזאת גם כל חלי וכל מכה וגו' , הזאת, לשון נקבה, מוסב על התורה. הזה, לשון זכר, מוסב על הספר, ועל ידי פסוק הטעמים הן נחלקין לשתי לשונות, בפרשת הקללות הטפחא נתונה תחת בספר, והתורה הזאת דבוקים זה לזה, לכך אמר הזאת, וכאן הטפחה נתונה תחת התורה, נמצא ספר התורה דבוקים זה לזה, לפיכך לשון זכר נופל אחריו, שהלשון נופל על הספר:
@17 **לא ידעום.** לא ידעו בהם גבורת אלהות: **ולא חלק להם.** לא נתנם לחלקם. ואונקלוס תרגם ולא אוטיבא להון, לא הטיבו להם שום טובה, ולשון לא חלק אותו אלוה שבחרו להם, לא חלק להם שום נחלה ושום חלק:
@19 **ויתשם ה'.** כתרגומו וטלטלנון, וכן (ירמיה יב, יד) הנני נותשם מעל אדמתם:
@20 **הנסתרת לה' אלהינו.** ואם תאמרו מה בידינו לעשות, אתה מעניש את הרבים על הרהורי היחיד, שנאמר (פסוק יז) פן יש בכם איש וגו' , ואחר כך (פסוק כא) וראו את מכות הארץ ההיא, והלא אין אדם יודע טמונותיו של חברו, אין אני מעניש אתכם על הנסתרות, שהן לה' אלהינו והוא יפרע מאותו יחיד, אבל הנגלות' לנו ולבנינו לבער הרע מקרבנו, ואם לא נעשה דין בהם יענשו הרבים. נקוד על לנו ולבנינו, לדרוש, שאף על הנגלות לא ענש את הרבים עד שעברו את הירדן, משקבלו עליהם את השבועה בהר גרזים ובהר עיבל, ונעשו ערבים זה לזה:
@23 **ושב ה' אלהיך את שבותך.** היה לו לכתוב והשיב את שבותך, רבותינו למדו מכאן שהשכינה כביכול שרויה עם ישראל בצרת גלותם, וכשנגאלין הכתיב גאלה לעצמו, שהוא ישוב עמהם. ועוד יש לומר, שגדול יום קבוץ גליות ובקשי, כאלו הוא עצמו צריך להיות אוחז בידיו ממש איש איש ממקומו, כענין שנאמר (ישעיה כז, יב) ואתם תלקטו לאחד אחד בני ישראל, ואף בגליות שאר האמות מצינו כן (ירמיהו מח, מז) ושבתי שבות מואב:
@31 **לא נפלאת היא ממך.** לא מכסה היא ממך, כמו שנאמר (דברים יז, ח) כי יפלא, ארי יתכסי, (איכה א, ט) ותרד פלאים, (איוב מ, יג) ותרד במטמוניות. מכסה, חבוש בטמון:
@32 **לא בשמים היא.** שאלו היתה בשמים, היית צריך לעלות אחריה וללמדה:
@34 **כי קרוב אליך.** התורה נתנה לכם בכתב ובעל פה:
@35 **את החיים ואת הטוב.** זה תלוי בזה, אם תעשה טוב הרי לך חיים, ואם תעשה רע הרי לך המות. והכתוב מפרש והולך היאך:
@36 **אשר אנכי מצוך היום לאהבה.** הרי הטוב, ובו תלוי: **וחיית ורבית.** הרי החיים:
@37 **ואם יפנה לבבך.** הרי הרע:
@38 **כי אבד תאבדון.** הרי המות:
@39 **העדתי בכם היום את השמים ואת הארץ.** שהם קימים לעולם וכאשר תקרה אתכם הרעה יהיו עדים שאני התריתי בכם בכל זאת. דבר אחר, העידתי בכם היום את השמים וגו' , אמר להם הקדוש ברוך הוא לישראל, הסתכלו בשמים שבראתי לשמש אתכם, שמא שנו את מדתם, שמא לא עלה גלגל חמה מן המזרח והאיר לכל העולם, כענין שנאמר (קהלת א, ה) וזרח השמש ובא השמש, הסתכלו בארץ שבראתי לשמש אתכם, שמא שנתה מדתה, שמא זרעתם אותה ולא צמחה, או שמא זרעתם חטים והעלתה שעורים, ומה אלו שנעשו לא לשכר ולא להפסד אם זוכין אין מקבלין שכר ואם חוטאין אין מקבלין פרענות, לא שנו את מדתם, אתם, שאם זכיתם תקבלו שכר, ואם חטאתם תקבלו פרענות על אחת כמה וכמה: **ובחרת בחיים.** אני מורה לכם שתבחרו בחלק החיים, כאדם האומר לחברו בחר לך חלק יפה בנחלתי, ומעמידו על חלק היפה ואומר לו, את זה ברור לך, ועל זה נאמר (תהלים טז, ה) ה' מנת חלקי וכוסי אתה תומיך גורלי, הנחת ידי על גורל הטוב לומר את זה קח לך:

@1 **אתם נצבים היום לפני ה' אלהיכם** . שאתם עומדים ומזומנים לפני השם כדי לעמוד בבריתו כי לקבל התורה בבאורה נאספו אליו או שהיו עומדים לפני הארון והברית הוא השבועה והאלה אשר יזכיר לעברך בברית ה' אלהיך ובאלתו ויתכן שכרת עוד עמם ברית כברית הראשונה אשר כרת אתם בהר סיני (שמות כד ה-ח) שהקריב עליהם עולה ולקח חצי הדם לזרוק על המזבח וחצי הדם זרק על העם אבל לא הוצרך להזכיר זה ועל דרך האמת כבר הודעתיך הברית הזאת וטעם ראשיכם שבטיכם ראשיכם ראשי שבטיכם כמו והנבואה עודד הנביא על דעת ר"א ועל דעתי הכתוב יכלול ויפרוט והכלל ראשיכם וכל שבטיכם וחזר ופרט זקניכם ושטריכם שהם ראשיכם כי זקן ונשוא פנים הוא הראש וכן אמר (להלן לא כח) הקהילו אלי את כל זקני שבטיכם ושוטריכם כי כל איש אשר לו שררה ומנוי על הצבור יקרא ראש נאמר בנשיאים (במדבר א טז) "ראשי אלפי ישראל" כי הם במעלה הגדולה לכל אלפי ישראל ונאמר במרגלים (שם יג ג) "ראשי בני ישראל "המה" שהם ראשים בבני ישראל לא ראשים לכל בני ישראל וכלם בכלל ראשיכם וחזר ואמר כל איש ישראל שהם שבטיכם והזכיר עוד הטף והנשים והגרים וחוטבי עצים ושואבי מים אשר להם מערב רב והביא שם הטף להביאם בברית כי אפילו עם הדורות העתידים יכרות ברית או כדי לזכותם כטעם שאמרו בהקהל (חגיגה ג) ורבותינו אמרו (יבמות עט) שבאו קצת כנענים בימי משה כדרך שבאו בימי יהושע ונתנם חוטבי עצים ושואבי מים לעדה ולמשכן ה' ואין הכונה לומר שרמו אותו אבל באו אליו להשלים עמו כי כן המשפט כאשר ביארנו (לעיל כ י יא) וכך מצאתי במדרש תנחומא (נצבים ב) ללמדך שבאו אצל משה ולא קבלם כלומר שלא יכלו לרמותו לכרות להם ברית אבל עשאם מיד חוטבי עצים ושואבי מים
@6 **ואת אשר איננו פה עמנו** . וגם עם הדורות העתידים להיות
@7 **כי אתם ידעתם** . וגו' ותראו את שקוציהם לפי שראיתם את האומות עובדי עבודת כוכבים ושמא השיא לב אחד מכם ללכת אחריהם
@9 **פן יש בכם וגו'** . לפיכך אני צריך להשביעכם לשון רש"י ויפה פירש והטעם לומר אני צריך להביאכם באלה ובשבועה עתה בברית הזאת מיראתי אולי נפתה לב קצתכם לשקוצי מצרים כאשר עשיתם בעגל או לשקוצי עמון ומואב אשר ראיתם בדרך כאשר היה לכם בבעל פעור כי בברית הראשונה של שעת מתן תורה לא היו שם אלות וקללות והזכיר איש או אשה מפני שהאשה דעתה קלה עליה וכן יעשה בענין ע"ז (לעיל יז ב) והזכיר יחידים ומשפחה ושבט שהוא עם רב ולא אמר על כולם דרך כבוד או שלא יתכן שיהיה לב כולם פונה היום לע"ז כי לא היו באים בברית השם ובאלתו כי מי יכריחם אבל משפחה או שבט יבואו בברית מפני פחד הרוב ואמר פן יש בכם וגו' אשר לבבו פנה היום על הנפתה כבר לע"ז והוא בלבו מאמין בה היום הזה או פן יש בכם שרש רע שיפרח וישגה ובימים הבאים יוציא פרחים רעים ויצמיח מרורות וזה על אשר איננו פה עמנו היום כי האב שרש והבן נצר משרשיו יפרה והזכיר השרש לומר כי הוא יכול להביא באלה הדורות הבאים שהשרש אשר ממנו יצמחו הוא לפניו היום והוא בא בברית ובאלה הזאת ואמר פרה ראש לרמוז כי משרש מתוק לא יצא מר וכל אשר לבבו שלם עם השם הנכבד ולא הרהר כלל בע"ז לא יוליד מודה בה ואל תקשה עלי בזה מן הכתוב (יחזקאל יח י) והוליד בן פריץ כי אמת הדבר וסוד גדול לא אוכל לפרש בו
@9 "וראש ולענה" - עשבים מרים או ממיתים ושמם כן בלשון הקדש או הם כנויים יקראו האחד "ראש" שהוא ראש המרורים מר מכולם והשני יקראו "לענה" מענין לענות מפני (שמות י ג) כי האוכל אותו נגש ונענה לענות נפשו יאכלנו
@10 **והתברך בלבבו לאמר** . כשישמע האחרים מתקללים באלות האלה הוא יתברך במחשבתו ויאמר בלבו שלום יהיה לי מכל אלה כאשר אלך בתאות לבי והשם לא יסלח לו אבל יעשן עליו אפו אז כשיחטא לדור או לדורות או יהיה טעם "כי" לאמר יהיה לי שלום בעבור שאינני מקבל עלי השבועה כי בשרירות לבי אלך כל ימי וכל חפצי אעשה ולא יאבה ה' בעבור שאיננו מקבל אלתו לסלוח לו אבל יעשן עליו אפו כיון שבא בבריתו לפני עם כל ישראל התאוה הגוברת ומתחזקת בלב תקרא שרירות כלשון חכמים (בבא בתרא קס) שריר וקיים וכן בשרירי בטנו (איוב מ טז) ופירוש למען ספות הרוה את הצמאה להוסיף השבעה עם המתאוה כי נפש שבעה תקרא רוה כענין ורויתי נפש הכהנים דשן ועמי את טובי ישבעו (ירמיהו לא יג) והיתה נפשם כגן רוה (שם פסוק יא) והמתאוה תקרא צמאה צמאה לך נפשי (תהלים סג ב) והטעם כי נפש האדם הרוה שאיננה מתאוה לדברים הרעים לה כאשר תבא בלבו קצת התאוה והוא ימלא תאותו אז יוסיף בנפשו תאוה יתירה ותהיה צמאה מאד לדבר ההוא שאכל או שעשה יותר מבראשונה ותתאוה עוד לדברים רעים שלא היתה מתאוה להם מתחלה כי המתאוה לזמת הנשים היפות כשיהיה שטוף בזמתן תבואהו תאוה לבוא על הזכר ועל הבהמה וכיוצא בזה בשאר התאוות וכענין שהזכירו חכמים (סוכה נב) משביעו רעב מרעיבו שבע ולכך יאמר הכתוב בהולך בשרירות לבו שהוא אם ימלא נפשו בתאוות השרירות והחזקות עליו אשר היא צמאה להם יוסיף נפשו הרוה עם הצמאה כי יתאוה ויצמא למה שהיה שבע ממנו וכאשר השביע נפשו בו ולפי שהזכיר "שרש פורה" אמר בלשון הזה כי יוסיף השרש הוא כפתו אשר היא רוה ורעננה עם הצמאה ותשובנה כולם צמאות ואין "למען" במקום הזה טעם שאלך בשרירות לבי בעבור שאספה הרוה עם הצמאה אבל הוא כמו "לספות" יאמר הכתוב כי בעבור זה יהיה כך כי בכל סבה עם עלול יאמר "למען" בין שיעשה אדם הגורם לרצותו בעלול כמו למען (אשר) ייטב לך בין שיהיה אדם הגורם כן שלא מדעתו כמו למען למוג לב (יחזקאל כא כ) למען יאשמו (שם ו ו) כספם וזהבם עשו לי עצבים למען יכרת (הושע ח ד) ורבים כאלה וזה הטוב והישר בעיני בפסוק הזה מכל הנכתב עליו בהרבה פנים גם יתכן לפרש שהוא שב אל שרש פורה וראש ולענה יאמר כי יתברך בלבבו לאמר שלום יהיה לי למען שיוסיף פארתו הרוה אשר תגדל ותצמיח הלענה וראש על הצמאה אשר לא היתה צומחת או יהיה "הרוה" כנוי ללענה הנזכרת שיוסיף הלענה הרוה הצומחת וגדלה מאד על הצמאה אשר לא היתה גדלה רק מעט ותהיינה שתיהן צומחות והכונה בזה לומר כי כל אשר ישמע האלה ויתברך ממנה ויתחזק בשרירותו סעיפיו ישיבוהו לחטוא ויצמיחו פשעים יותר מבראשונה וגם זה פירוש נכון
@11 **יעשן אף ה' וקנאתו באיש ההוא** . אלת היחיד איש או אשה ומחה ה' את שמו אלת המשפחה כי שם אחד לראש בית אבותם והבדילו ה' לרעה לשבט מכל שבטי ישראל הנשארים
@13 **ואמר הדור האחרון בניכם אשר יקומו** . כי שבטי ישראל בדור הראשון כבר ידעו זה כי הם שמעו אלות הברית ויתכן כי הכתוב הזה יחזור על שרש פורה ראש ולענה כי כשיקרה זה בדורות הבאים אז ישאלו כן
@17 **אלהים אשר לא ידעום** . לא ידעו בהם גבורת אלהות ולא חלק להם ולא נתנם לחלקם ואונקלוס תרגמו ולא אוטיב להון לא הטיב להם שום טובה ולשון "חלק" אותו אלוה שבחרו להם לא חלק להם שום נחלה וחלק לשון רש"י והנכון אלהים אשר לא ידעום באלהים כלומר שלא ידעו אותם בכח אלהות שימצא להם מעצמו ולא חלקם ה' אלהי אבותם להם שלא נתן אותם שרים על ישראל כאשר שמם על האומות וכבר פירשתי זה (ויקרא יח כה)
@19 **ויתשם ה' מעל אדמתם** . כי יגלה השבט העושה הרע בעיני ה' כענין ויגלם לראובני ולגדי (דברי הימים א ה כו) והנכון כי עתה ירמוז לגלות כל ישראל להיותם כלם רעים ויגלו גלות שלימה וכן בפרשה הבאה אחרי כן (להלן ל א) והיה כי יבאו עליך כל הדברים האלה על גלות כל ישראל יהיה כמו שאמר (שם) בכל הגוים אשר הדיחך ה' אלהיך שמה וגו' והפרשה כולה
@20 **הנסתרות לה' אלהינו** . על דעת המפרשים יאמר כי השם אלהינו לו לעשות משפט בעובדי עבודה זרה בסתר כי כל התעלומות גלויות לפניו והנגלות עלינו ועל בנינו לעשות להם את כל דברי התורה הזאת להכות עובדי עובדה זרה כדין התורה וגם כפי המדרש (סנהדרין מג) כן הוא ודעתי בדרך הפשט כי "הנסתרות" הם החטאים הנסתרים מן העושים אותם כמו שגיאות מי יבין מנסתרות נקני (תהלים יט יג) יאמר הנסתרות לשם לבדו הם אין לנו בהן עון אשר חטא אבל הנגלות שהם הזדונות לנו ולבנינו עד עולם לעשות את כל דברי התורה הזאת חוקת עולם שכך קבלנו על אשר ישנו פה ועל אשר איננו פה לדורות עולם ולפי שהביא באלה לעשות כל המצוה הוציא מן החרם העושה בשגגה שלא יתקלל באלה הזאת ודברי אונקלוס מטין כן שאמר דמטמרן קדם ה' אלהנא ואם כדברי המפרשים ראוי לו לומר דמטמרין לה' אלהנא
@21 **והיה כי יבאו עליך כל הדברים האלה** . כבר הזכרתי (ויקרא כו טז) כי הפרשה הזאת עתידה כי כל עניניה לא היו ולא נבראו אבל הם עתידין להיות
@22 **וטעם ושבת עד ה' אלהיך ושמעת בקלו ככל אשר אנכי מצוך היום אתה ובניך** . שתשוב אל ה' בכל לבבך ובכל נפשך ותקבל עליך ועל בניך לדורותם לעשות ככל אשר אנכי מצוך היום כאשר עשו בגאולה השנית דכתיב (נחמיה י ל) ובאים באלה ובשבועה ללכת בתורת האלהים אשר נתנה ביד משה עבד האלהים ולשמור ולעשות את כל מצות ה' אדנינו ומשפטיו וחקיו או יהיה "מצוך אתה ובניך" כמו מצוך לך ולבניך כענין ואתה צוית (בראשית מה יט) וכן וירעו אותנו (לעיל כו ו) לנו ולפי דעתי יש בו סוד גדול כי ירמוז למה שאמרו (יבמות סג) אין בן דוד בא עד שיכלו כל הנשמות שבגוף וכבר דברתי בו
@26 **ומל ה' אלהיך את לבבך** . זהו שאמרו (שבת קד) הבא לטהר מסייעין אותו מבטיחך שתשוב אליו בכל לבבך והוא יעזור אותך ונראה מן הכתובים ענין זה שאומר כי מזמן הבריאה היתה רשות ביד האדם לעשות כרצונו צדיק או רשע וכל זמן התורה כן כדי שיהיה להם זכות בבחירתם בטוב ועונש ברצותם ברע אבל לימות המשיח תהיה הבחירה בטוב להם טבע לא יתאוה להם הלב למה שאינו ראוי ולא יחפוץ בו כלל והיא המילה הנזכרת כאן כי החמדה והתאוה ערלה ללב ומול הלב הוא שלא יחמוד ולא יתאוה וישוב האדם בזמן ההוא לאשר היה קודם חטאו של אדם הראשון שהיה עושה בטבעו מה שראוי לעשות ולא היה לו ברצונו דבר והפכו כמו שפירשתי בסדר בראשית (ב ט) וזהו מה שאמר הכתוב בירמיה (לא ל- לב) הנה ימים באים נאם ה' וכרתי את בית ישראל ואת בית יהודה ברית חדשה לא כברית אשר כרתי את אבותם וגו' כי זאת הברית אשר אכרות את בית ישראל אחרי הימים ההם נתתי את תורתי בקרבם ועל לבם אכתבנה וזהו בטול יצר הרע ועשות הלב בטבעו מעשהו הראוי ולכך אמר עוד (שם פסוקים לב לג) והייתי להם לאלהים והמה יהיו לי לעם ולא ילמדו עוד איש את רעהו ואיש את אחיו לאמר דעו את ה' כי כולם ידעו אותי למקטנם ועד גדולם ובידוע כי יצר לב האדם רע מנעוריו וצריכים ללמד אותם אלא שיתבטל יצרם בזמן ההוא לגמרי וכן נאמר ביחזקאל (לו כו כז) ונתתי לכם לב חדש ורוח חדשה אתן בקרבכם וגו' ועשיתי את אשר בחקי תלכו והלב החדש ירמוז לטבעו והרוח לחפץ ולרצון וזהו שאמרו רבותינו (שבת קנא) והגיעו שנים אשר תאמר אין לי בהם חפץ (קהלת יב א) אלו ימות המשיח שאין בהם לא זכות ולא חובה כי בימי המשיח לא יהיה באדם חפץ אבל יעשה בטבעו המעשה הראוי ולפיכך אין בהם לא זכות ולא חובה כי הזכות והחובה תלויים בחפץ
@31 **וטעם כי המצוה הזאת** . על כל התורה כולה והנכון כי על כל התורה יאמר (לעיל ח א) "כל המצוה אשר אנכי מצוך היום" אבל "המצוה הזאת" על התשובה הנזכרת כי והשבות אל לבבך (בפסוק א) ושבת עד ה' אלהיך (בפסוק ב) מצוה שיצוה אותנו לעשות כן ונאמרה בלשון הבינוני לרמוז בהבטחה כי עתיד הדבר להיות כן והטעם לאמר כי אם יהיה נדחך בקצה השמים ואתה ביד העמים תוכל לשוב אל ה' ולעשות ככל אשר אנכי מצוך היום כי אין הדבר נפלא ורחוק ממך אבל קרוב אליך מאד לעשותו בכל עת ובכל מקום וזה טעם בפיך ובלבבך לעשותו שיתודו את עונם ואת עון אבותם בפיהם וישובו בלבם אל ה' ויקבלו עליהם היום התורה לעשותה לדורות כאשר הזכיר (לעיל פסוק ב) אתה ובניך בכל לבבך כמו שפירשתי (שם)
@35 **ראה נתתי לפניך היום** . יחזור להזהירם עוד להגיד להם כי שני הדרכים בידם וברשותם ללכת באשר יחפצו בה ואין מונע ומעכב בידם לא מן התחתונים ולא מן העליונים ויעיד בהם את השמים ואת הארץ פעם שנית (פסוק יט) אחר שאמר (לעיל ד כו) העידתי בכם היום את השמים ואת הארץ כי אבד תאבדון מהר כי עתה יאמר העדותי בכם היום את השמים ואת הארץ כי החיים והמות נתתי לפניך שהם הברכה והקללה וכי יעצתיך שתבחר בחיים למען תחיה אתה וזרעך והנה הוא כמחתים העדים בסוף דבריו כולם
